import sys

def main():
    data = sys.stdin.read().split()
    s = data[0]
    m = int(data[1])
    words = data[2:2 + m]
    waiting = {}
    for wi, w in enumerate(words):
        waiting.setdefault(w[0], []).append((wi, 1))
    count = 0
    for ch in s:
        lst = waiting.pop(ch, None)
        if not lst:
            continue
        for wi, pos in lst:
            w = words[wi]
            if pos == len(w):
                count += 1
            else:
                waiting.setdefault(w[pos], []).append((wi, pos + 1))
    print(count)

